/* Peripherals the sources reach into (`RCC->CSR`). Each is a block of RAM on
 * the host, so a test can SET a register before the call and READ it after:
 *
 *     RCC->CSR = RCC_CSR_PINRSTF;    reset_cause_capture();
 *
 * Only the registers the sources use, in name order - not the vendor's
 * layout, so never assert on an offset or a sizeof. host_peripherals_reset()
 * (host_vendor_fakes.h) zeroes them all. HOST_PERIPHERAL_<name> says which
 * exist. */
#ifndef CoreDebug
#define HOST_PERIPHERAL_CoreDebug 1
typedef struct {
    volatile uint32_t DEMCR;
} host_peripheral_CoreDebug_t;
extern host_peripheral_CoreDebug_t host_peripheral_CoreDebug;
#define CoreDebug (&host_peripheral_CoreDebug)
#endif
